  'section.detail.pobles.viquipedia.explica': 'Á ficha deste pobo fáltanlle datos. O teu navegador pode traelos da Viquipèdia (a Wikipedia en catalán), Wikidata e Wikimedia Commons, que son públicas e libres. Ata que non premes o botón non se conecta con ninguén. Cando o premes, Wikimedia recibe o nome do pobo e o teu enderezo IP, sen cookies nin o enderezo desta páxina. O que traia gárdase só neste navegador, e non se escribe nada no servidor de Sóc de Poble.',
