  'section.translations.pages.title': 'Tradutor de Pobo para páxinas',
  'section.translations.pages.lead': 'Traduce a páxina que estás a ler sen saír dela: con Apertium, software libre, e, para o éuscaro e o alemán, con MyMemory.',
  'section.translations.pages.card.title': 'Botón «Traduir» da barra azul',
  /* Gauntlet 261030 (cicle 2, traductor-client) · A aplicación nativa e os textos do Tradutor de Pobo. */
  'section.translations.pages.card.natiu': 'Na aplicación nativa, polo de agora, o botón aínda non traduce nada: se o premes, dío.',
  'section.traduir.menu': 'Traducir a páxina',
  'section.traduir.original': 'Orixinal (valenciano)',
  'section.traduir.traduit': 'Traducido automaticamente do valenciano',
  'section.traduir.veureOriginal': 'Ver o orixinal',
  'section.traduir.traduint': 'Traducindo…',
  'section.traduir.avis.senseTraductor': 'A tradución automática non está dispoñible neste servidor.',
  'section.traduir.avis.error': 'Non se puido traducir a páxina. Téntao de novo máis tarde.',
  'section.traduir.avis.massaLlarga': 'Esta páxina é demasiado longa para traducila automaticamente.',
  'section.traduir.avis.senseConnexio': 'Non se puido conectar co servizo de tradución.',
  'section.traduir.avis.senseText': 'Esta páxina non ten texto que traducir.',
  'section.traduir.avis.limit': 'Chegouse ao límite de traducións automáticas. Téntao de novo máis tarde.',
  'section.traduir.avis.ocupat': 'O servizo de tradución está ocupado. Téntao de novo nun momento.',
  'section.translations.pages.card.body': 'O botón «Traduir» da barra azul traduce a páxina ao castelán, ao galego, ao éuscaro, ao inglés, ao francés e ao alemán. Para o castelán, o galego, o inglés e o francés faino con Apertium, un tradutor de software libre. Para o éuscaro e o alemán, que Apertium non ofrece desde o valenciano, faino con MyMemory, o servizo da empresa italiana Translated, que non di que motor automático emprega. Só cando escolles unha lingua, o texto da páxina sae cara ao tradutor: en socdepoble.org, desde o teu navegador directamente ao servizo, que ve o teu enderezo IP; nun sitio con servidor propio, como WordPress, a través dese servidor, que pode ter configurado outro provedor. MyMemory pode gardar os textos que recibe e rexistrar o enderezo IP, e o éuscaro e o alemán teñen un límite diario de traducións. Por iso só se traduce o texto das páxinas públicas, nunca as túas mensaxes nin as túas notas. Onde non hai tradución, o botón indícao.',
  'section.translations.dynamic.title': 'Tradución dinámica de tarxetas',
  'section.translations.dynamic.lead': 'Como funciona a tradución do contido creado polos usuarios doutras vilas.',
  'section.translations.engine.title': 'Motor de tradución integrado',
  'section.translations.engine.body': 'Ademais do idioma base da interface, as Tarxetas (Muro, Chats, Mercado e Eventos) contarán cun motor de tradución automática. Permitirache ler ao instante o que escriben usuarios doutras vilas do estado (por exemplo, se alguén publica en éuscaro ou en galego) traducíndoo á túa lingua de preferencia.',
  'section.translations.howto.title': 'Como usalo',
  'section.translations.howto.body': 'Busca a icona de tradución dentro das publicacións das tarxetas: servirá para traducir só esa mensaxe ou publicación concreta. Mentres a tradución de tarxetas non estea conectada, o botón leva a esta páxina.',
  'section.translations.note.title': 'Nota',
  'section.translations.note.body': 'As traducións automáticas poden conter pequenos erros de interpretación cando se trata de expresións moi locais ou frases feitas de cada territorio.',
  'section.connectar.kicker': 'Conectar',
  'section.connectar.title': 'Onde queres continuar?',
  'section.connectar.subtitle': 'Escolle o espazo no que queres entrar e segue navegando.',
