  'section.connectar.autor.text': 'Abre unha conversa privada con {nom}. Aparecerá axiña na súa lista de conversas, pero non recibirá ningunha mensaxe ata que a escribas.',
  'section.connectar.autor.textLlavor': 'Abre unha conversa privada con {nom} neste dispositivo. Non recibirá ningunha mensaxe ata que a escribas.',
