  'section.connectar.autor.botoCom': 'Escríbelle a {nom} como {persona}',
  'section.connectar.autor.textCom': 'O chat é persoal: {nom} verá que lle escribe {persona}, non {entitat}, que aquí non ten chat propio.',
  'section.connectar.titular.intro': '{nom} é titular de {entitat} e escolleu que se vexa aquí.',
  'section.connectar.lead': 'Escolle onde chega (por defecto, á Safata d’Entrada), quen o pode ver e como o atoparás despois.',
  'section.connectar.leadCamins': 'Cada camiño ten o seu botón: conectar con alguén ou escribirlle non te fai membro de nada. Se gardas o elemento nas túas notas en privado, non avisa a ninguén; se escolles persoas ou grupos de chat, enviarémoslles a ligazón.',
