  'section.perfil.privacitat.dades.explica': 'Descarga unha copia dos datos que Sóc de Poble garda da túa conta: perfil, organizacións, publicacións, notas, conversas, a lista dos teus ficheiros e anexos, consentimentos, as denuncias que fixeches, as persoas e entidades que bloqueaches ou que segues e as normas que aceptaches. Para protexer outras persoas, non indicamos quen te denunciou, quen te bloqueou nin quen te segue: das denuncias sobre ti só consta cantas remataron cunha medida (se queres o detalle, pídenolo por correo) e, de quen te segue, cantas persoas son. Tampouco incluímos as pegadas do enderezo IP nin o permiso cifrado de Apple. É un ficheiro JSON que podes abrir con calquera editor de texto.',
  'section.perfil.privacitat.dades.fet': 'Xa tes o ficheiro {nom} nas descargas.',
  'section.perfil.privacitat.dades.descarrega': 'Descargar os meus datos',
  'section.perfil.privacitat.dades.error': 'Non se puideron preparar os teus datos. Téntao de novo.',
  'section.perfil.privacitat.politica.llegir': 'Ler a política',
  'section.perfil.privacitat.politica.oblitRuralResum': 'Esquecemento Saudable Rural: a memoria histórica de Sóc de Poble, El Rentonar e a Coordinadora d’Estudis Eòlics del Comtat, xunto coas publicacións fixadas e os marcadores, queda sempre blindada e nunca caduca.',
  'section.perfil.privacitat.consentiment.titol': 'Consentimento',
  'section.perfil.privacitat.consentiment.comprovant': 'Comprobando o consentimento…',
  'section.perfil.privacitat.consentiment.errorLectura': 'Non se puido ler o estado do consentimento.',
  'section.perfil.privacitat.consentiment.errorRegistre': 'Non se puido rexistrar o consentimento.',
  'section.perfil.privacitat.consentiment.errorRetirada': 'Non se puido retirar o consentimento.',
  'section.perfil.privacitat.consentiment.senseConstancia': 'Non consta que aceptases a política de privacidade.',
  'section.perfil.privacitat.consentiment.acceptada': 'Aceptáchela (versión {versio}) o {data}.',
  'section.perfil.privacitat.consentiment.retirada': 'Retiráchela o {data}.',
  'section.perfil.privacitat.consentiment.vigent': 'Política de privacidade vixente: versión {versio}.',
  'section.perfil.privacitat.consentiment.senseVigent': 'Aínda non hai ningunha política de privacidade publicada.',
  'section.perfil.privacitat.consentiment.calTitol': 'Necesitamos o teu consentimento',
  'section.perfil.privacitat.consentiment.accepta': 'Aceptar a versión {versio}',
  'section.perfil.privacitat.consentiment.calText': 'Sen aceptar a política vixente non apareces no padrón do pobo.',
  'section.perfil.privacitat.consentiment.retira': 'Retirar o consentimento',
  'section.perfil.privacitat.consentiment.retiraDescripcio': 'Deixarás de aparecer no padrón do pobo ata que o volvas aceptar.',
  'section.perfil.privacitat.consentiment.retiraConfirma': 'Retiralo',
  'section.perfil.privacitat.consentiment.retiraText': 'A conta non se borra: para iso, pide a baixa. O rexistro de cando o deches e o retiraches consérvase, porque a lei nos obriga a poder demostralo.',
  'section.perfil.privacitat.baixa.titol': 'Darse de baixa',
  'section.perfil.privacitat.baixa.comprovant': 'Comprobando o estado da conta…',
  'section.perfil.privacitat.baixa.errorLectura': 'Non se puido comprobar se tes unha baixa pendente.',
  'section.perfil.privacitat.baixa.errorDemanda': 'Non se puido solicitar a baixa.',
  'section.perfil.privacitat.baixa.cancelada': 'Baixa cancelada. O teu perfil volve ser como era.',
  'section.perfil.privacitat.baixa.errorCancela': 'Non se puido cancelar a baixa.',
  'section.perfil.privacitat.baixa.pendentTitol': 'Tes unha baixa pendente',
  'section.perfil.privacitat.baixa.cancela': 'Cancelar a baixa',
  'section.perfil.privacitat.baixa.pendent': 'Solicitáchela o {demanada}. A conta, as túas publicacións persoais e os teus ficheiros borraranse definitivamente o {purga}, agás os ficheiros que aínda usa unha entidade (a súa ficha ou unha publicación) ou unha publicación doutra persoa. {apple}',
  'section.perfil.privacitat.baixa.esperaApple': 'Se entraches con Apple e aínda non puidemos retirar o permiso, o borrado pode esperar ata {diesApple} días máis.',
  'section.perfil.privacitat.baixa.explica': 'Se te vas, no momento ocultamos o teu perfil: deixa de aparecer no padrón, poñémoslle un nome xenérico en lugar do teu e quitámoslle a foto. Tes {dies} días para arrepentirte. Pasado ese prazo, bórranse para sempre a conta, as túas publicacións persoais e os teus ficheiros, agás os que aínda usa unha entidade (a súa ficha ou unha publicación) ou unha publicación doutra persoa; o que publicaches en nome dunha entidade queda na entidade. {apple}',
  'section.perfil.privacitat.baixa.boto': 'Darme de baixa',
  'section.perfil.privacitat.baixa.dialegTitol': 'Darte de baixa',
  'section.perfil.privacitat.baixa.dialegDescripcio': 'Tes {dies} días de graza para botarte atrás.',
  'section.perfil.privacitat.baixa.confirma': 'Si, darme de baixa',
  'section.perfil.privacitat.baixa.punt.amaga': 'Agora mesmo ocultamos o teu perfil: deixa de aparecer no padrón, poñémoslle un nome xenérico en lugar do teu e quitámoslle a foto, e as túas publicacións deixan de mostrar o teu nome e a túa foto.',
  'section.perfil.privacitat.baixa.punt.cancela': 'Durante {dies} días podes cancelala: entra de novo como sempre (co correo, Apple ou Google), volve a «Privacidade e datos» e preme «Cancelar a baixa».',
  'section.perfil.privacitat.baixa.punt.apple': 'Se entraches con Apple, ao solicitar a baixa tentamos retirar o permiso que lle deches a Sóc de Poble; se non o conseguimos, podes retiralo ti en Axustes › o teu nome › Iniciar sesión con Apple, ou en account.apple.com. Se cando pasen os {dies} días aínda non o puidemos retirar, o borrado definitivo pode esperar ata {diesApple} días máis. Se o retiramos e volves entrar con Apple para cancelar a baixa, Apple pedirache permiso de novo.',
  'section.perfil.privacitat.baixa.punt.esborrat': 'Pasados os {dies} días, bórranse definitivamente a conta, as túas publicacións persoais e os teus ficheiros, agás os que aínda usa unha entidade (a súa ficha ou unha publicación) ou unha publicación doutra persoa. O que publicaches en nome dunha entidade queda na entidade.',
  'section.perfil.privacitat.baixa.punt.conserva': 'Gárdanse, xa sen a túa conta pero non de todo anónimas, a proba do consentimento, que a lei nos obriga a conservar, e, para o historial de moderación, as denuncias que fixeches e as que outras persoas fixeron sobre ti ou sobre o teu contido, co identificador interno que tiña a túa conta.',
  'section.perfil.privacitat.baixa.punt.sessio': 'Pecharase a sesión en todos os teus dispositivos.',
  'section.perfil.privacitat.baixa.motiu': 'Por que te vas? (opcional)',
  'section.perfil.privacitat.baixa.motiuAjuda': 'Axúdanos a mellorar. Como máximo 500 caracteres.',
