  'section.xat.xifratge.public': "Conversa pública: pode lela calquera persoa que entre e non está cifrada de extremo a extremo.",
  'section.xat.xifratge.sensePrimitives': "Desde este enderezo non se pode cifrar. Abre Sóc de Poble na app ou en socdepoble.org para ler e escribir nesta conversa.",
  'section.xat.xifratge.canviInesperat': "Esta conversa cambiou no servidor de xeito inesperado. Por seguridade, non se pode escribir nela.",
  'section.xat.xifratge.entitatPendent': "As conversas con entidades aínda non se poden cifrar de extremo a extremo: desde este dispositivo, polo de agora, non se pode escribir nelas.",
  'section.xat.xifratge.clauCanviadaForta': "{nom} ten unha chave de seguridade nova que a chave anterior non confirmou. Pasa cando alguén perde o dispositivo e a frase, ou se alguén se meteu polo medio. Fala con {nom} para saber que pasou.",
  'section.xat.xifratge.numero.titol': "Número de seguridade",
  'section.xat.xifratge.numero.explica': "Se este número é igual no teu dispositivo e no de {nom}, ninguén cambiou as vosas chaves polo camiño. Comparádeo en persoa ou por teléfono.",
  'section.xat.xifratge.numero.calculant': "Calculando o número de seguridade…",
  'section.xat.xifratge.numero.marca': "Marcar como verificado",
  'section.xat.xifratge.numero.desmarca': "Quitar a marca de verificado",
  'section.xat.xifratge.numero.verificat': "Verificado: comparaches este número con {nom}.",
  'section.xat.xifratge.numero.senseClau': "{nom} aínda non activou as conversas privadas cifradas en ningún dispositivo: aínda non hai ningún número que comparar.",
  'section.xat.xifratge.numero.senseClausPropies': "Este dispositivo aínda non ten as túas chaves das conversas privadas: aínda non hai ningún número que comparar.",
  'section.xat.xifratge.numero.canviat': "A chave de {nom} cambiou mentres mirabas o número. Comparade este número novo antes de marcalo.",
